import React, { useState, useEffect } from "react";
import styled from "styled-components";
import { useParams } from "react-router-dom";

const FuelPageContainer = styled.div`
  padding: 20px;
  font-family: Arial, sans-serif;
`;

const Table = styled.table`
  width: 100%;
  border-collapse: collapse;
  margin-top: 20px;
`;

const TableRow = styled.tr`
  border: 1px solid #ddd;
  padding: 8px;
`;

const TableHeader = styled.th`
  border: 1px solid #ddd;
  padding: 8px;
  background-color: #f2f2f2;
`;

const TableCell = styled.td`
  border: 1px solid #ddd;
  padding: 8px;
`;

const Form = styled.form`
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 20px;
`;

const Input = styled.input`
  padding: 10px;
  border: 1px solid #ddd;
  border-radius: 5px;
`;

const Button = styled.button`
  padding: 10px;
  border: none;
  background: #007bff;
  color: white;
  cursor: pointer;
  border-radius: 5px;

  &:hover {
    background: #0056b3;
  }
`;

const FuelPage = () => {
  const { id } = useParams();
  const [fuelData, setFuelData] = useState([]);
  const [newFuel, setNewFuel] = useState({
    fill_date: "",
    bunk_name: "",
    total_amount: "",
    amount_paid: "",
  });
  const [loading, setLoading] = useState(false);

  const fetchFuelData = async () => {
    setLoading(true);
    try {
      const response = await fetch(`http://localhost:5001/api/fuel/${id}`);
      const data = await response.json();
      setFuelData(data);
    } catch (error) {
      console.error("Error fetching fuel data:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchFuelData();
  }, [id]);

  const handleInputChange = (e) => {
    setNewFuel({ ...newFuel, [e.target.name]: e.target.value });
  };

  const handleAddFuel = async (e) => {
    e.preventDefault();
    try {
      const response = await fetch("http://localhost:5001/api/fuel/add", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          lorry_id: id,
          ...newFuel,
        }),
      });
      if (response.ok) {
        alert("Fuel details added successfully!");
        setNewFuel({
          fill_date: "",
          bunk_name: "",
          total_amount: "",
          amount_paid: "",
        });
        fetchFuelData(); // Call the function to refresh data
      } else {
        alert("Error adding fuel data");
      }
    } catch (error) {
      console.error("Error adding fuel data:", error);
    }
  };

  const handleDeleteFuel = async (fuelId) => {
    try {
      const response = await fetch(
        `http://localhost:5001/api/fuel/delete/${fuelId}`,
        { method: "DELETE" }
      );
      if (response.ok) {
        alert("Fuel record deleted successfully!");
        fetchFuelData(); // Call the function to refresh data
      } else {
        alert("Error deleting fuel record");
      }
    } catch (error) {
      console.error("Error deleting fuel record:", error);
    }
  };

  return (
    <FuelPageContainer>
      <h1>Fuel Details for Lorry ID: {id}</h1>
      <Form onSubmit={handleAddFuel}>
        <Input
          type="date"
          name="fill_date"
          value={newFuel.fill_date}
          onChange={handleInputChange}
          required
        />
        <Input
          type="text"
          name="bunk_name"
          placeholder="Bunk Name"
          value={newFuel.bunk_name}
          onChange={handleInputChange}
          required
        />
        <Input
          type="number"
          name="total_amount"
          placeholder="Total Amount"
          value={newFuel.total_amount}
          onChange={handleInputChange}
          required
        />
        <Input
          type="number"
          name="amount_paid"
          placeholder="Amount Paid"
          value={newFuel.amount_paid}
          onChange={handleInputChange}
          required
        />
        <Button type="submit">Add Fuel Record</Button>
      </Form>

      {loading ? (
        <p>Loading fuel details...</p>
      ) : fuelData.length > 0 ? (
        <Table>
          <thead>
            <tr>
              <TableHeader>Date</TableHeader>
              <TableHeader>Bunk Name</TableHeader>
              <TableHeader>Total Amount</TableHeader>
              <TableHeader>Amount Paid</TableHeader>
              <TableHeader>Remaining Amount</TableHeader>
              <TableHeader>Actions</TableHeader>
            </tr>
          </thead>
          <tbody>
            {fuelData.map((fuel, index) => (
              <TableRow key={index}>
                <TableCell>{fuel.fill_date}</TableCell>
                <TableCell>{fuel.bunk_name}</TableCell>
                <TableCell>{fuel.total_amount}</TableCell>
                <TableCell>{fuel.amount_paid}</TableCell>
                <TableCell>
                  {fuel.total_amount - fuel.amount_paid}
                </TableCell>
                <TableCell>
                  <Button onClick={() => handleDeleteFuel(fuel.id)}>
                    Delete
                  </Button>
                </TableCell>
              </TableRow>
            ))}
          </tbody>
        </Table>
      ) : (
        <p>No fuel records available.</p>
      )}
    </FuelPageContainer>
  );
};

export default FuelPage;
